import java.util.*;
import java.io.*;

public class Main {
    static final long MOD1 = 998244353L;
    static final long MOD2 = 1000000007L;
    static long totalResult = 0;
    static long totalN;
    static long count1 = 0;
    static List<Long>[] valSet = new ArrayList[7];
    static long[] sumSet = new long[7];
    static long count2 = 0;
    static long[] powTenArr = {1, 10, 100, 1000, 10000, 100000, 1000000};

    public static void generateValues(int level, long prefixSum) {
        if (level == 7) return;
        long val = (count1 - prefixSum + MOD1) % MOD1;
        valSet[level].add(val);
        sumSet[level] += val;
        count1++;
        for (int digit = 0; digit <= 9; digit++) {
            generateValues(level + 1, prefixSum * 10 + digit);
        }
    }

    public static boolean checkRange(long x) {
        long half = 1000000L;
        return x * half + 999999L <= totalN && x * half * 10 > totalN;
    }

    public static void traverseAll(int level, long number) {
        if (number > totalN) return;
        if (checkRange(number)) {
            for (int i = 0; i <= 6; i++) {
                long offset = ((count2 + 1 - (number * powTenArr[i]) % MOD1) + MOD1) % MOD1;
                List<Long> list = valSet[i];
                int pos = lowerBound(list, (MOD1 - offset) % MOD1);
                long sumVal = sumSet[i];
                long size = list.size();
                long temp = (sumVal + offset * size - MOD1 * (size - pos)) % MOD2;
                if (temp < 0) temp += MOD2;
                totalResult = (totalResult + temp) % MOD2;
            }
            count2 += count1;
        } else {
            count2++;
            long tempVal = ((count2 - number) % MOD1 + MOD1) % MOD1;
            totalResult = (totalResult + tempVal) % MOD2;
            for (int digit = 0; digit <= 9; digit++) {
                if (level == 0 && digit == 0) continue;
                traverseAll(level + 1, number * 10 + digit);
            }
        }
    }

    public static int lowerBound(List<Long> list, long key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        totalN = Long.parseLong(br.readLine().trim());
        for (int i = 0; i < 7; i++) {
            valSet[i] = new ArrayList<>();
        }
        generateValues(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(valSet[i]);
        }
        count2 = -1;
        traverseAll(0, 0);
        System.out.println(totalResult);
    }
}
